/**
 * Signed in, the account's language wins on this device; a French choice saved on the device
 * before accounts had a language (localStorage "locale") is moved to the account once.
 *
 * Value: protects=sign-in applies the account language; a legacy "fr" is PUT to /auth/me once,
 * kept for a retry when that fails; registration sends the page language; fails_when=
 * adoptLegacyLocale or signIn's setLocale is dropped or the key is cleared before the save
 * succeeds; why_new=no test covered auth-context.tsx; seam=none
 * Generated by /ship test coverage audit (pass 1).
 */
import { useEffect } from "react";
import { act, render, screen, waitFor } from "@testing-library/react";
import { I18nProvider, useTranslation } from "./i18n";
import { AuthProvider, useAuth, type User } from "./auth-context";
import type { Locale } from "./locale";

const mockGet = jest.fn();
const mockPost = jest.fn();
const mockPut = jest.fn();
jest.mock("./api-client", () => ({
  api: {
    get: (...args: unknown[]) => mockGet(...args),
    post: (...args: unknown[]) => mockPost(...args),
    put: (...args: unknown[]) => mockPut(...args),
  },
}));
jest.mock("@/lib/signup-source", () => ({ takeSignupSource: () => null }));

const account = (locale: Locale): User => ({ id: "u1", email: "a@b.co", role: "investor", locale });

// Filled by Probe on each render: a holder object, since a component may not reassign an
// outer variable (react-hooks lint)
const probe = {} as { auth: ReturnType<typeof useAuth> };
function Probe() {
  const auth = useAuth();
  const { locale } = useTranslation();
  useEffect(() => {
    probe.auth = auth;
  });
  return <p data-testid="locale">{locale}</p>;
}

function renderAuth(initialLocale: Locale = "en") {
  render(
    <I18nProvider initialLocale={initialLocale}>
      <AuthProvider>
        <Probe />
      </AuthProvider>
    </I18nProvider>
  );
}

const shownLocale = () => screen.getByTestId("locale").textContent;

beforeEach(() => {
  mockGet.mockReset();
  mockPost.mockReset();
  mockPut.mockReset();
  localStorage.clear();
  // setLocale writes these too: reset them so no test passes on a previous one's switch
  document.documentElement.lang = "en";
  document.cookie = "locale=; max-age=0; path=/";
});

describe("AuthProvider and the account language", () => {
  it("switches the device to the account language on sign-in", async () => {
    mockPost.mockResolvedValue({ token: "t", user: account("fr") });
    renderAuth("en");
    await waitFor(() => expect(probe.auth.loading).toBe(false));

    await act(() => probe.auth.login("a@b.co", "password123"));

    expect(shownLocale()).toBe("fr");
    expect(document.documentElement.lang).toBe("fr");
    expect(mockPut).not.toHaveBeenCalled();
  });

  // Value: protects=an account language this build does not ship yet (the server learned it
  // first) shows English instead of breaking translation; fails_when=the isLocale guard in signIn
  // is removed; why_new=the other sign-in tests only use en and fr; seam=none
  it("reads a language this build does not ship as English", async () => {
    mockPost.mockResolvedValue({ token: "t", user: { ...account("en"), locale: "de" as Locale } });
    renderAuth("fr");
    await waitFor(() => expect(probe.auth.loading).toBe(false));

    await act(() => probe.auth.login("a@b.co", "password123"));

    expect(shownLocale()).toBe("en");
    expect(document.documentElement.lang).toBe("en");
  });

  it("saves a French choice left on the device to the account, once", async () => {
    localStorage.setItem("locale", "fr");
    mockPost.mockResolvedValue({ token: "t", user: account("en") });
    mockPut.mockResolvedValue(account("fr"));
    renderAuth("en");
    await waitFor(() => expect(probe.auth.loading).toBe(false));

    await act(() => probe.auth.login("a@b.co", "password123"));

    expect(mockPut).toHaveBeenCalledWith("/auth/me", { locale: "fr" });
    expect(localStorage.getItem("locale")).toBeNull();
    expect(shownLocale()).toBe("fr");
  });

  it("keeps the old choice for the next sign-in when saving it fails", async () => {
    localStorage.setItem("locale", "fr");
    mockPost.mockResolvedValue({ token: "t", user: account("en") });
    mockPut.mockRejectedValue(new Error("offline"));
    renderAuth("en");
    await waitFor(() => expect(probe.auth.loading).toBe(false));

    await act(() => probe.auth.login("a@b.co", "password123"));

    expect(localStorage.getItem("locale")).toBe("fr");
    expect(shownLocale()).toBe("en");
  });

  it("drops an old English choice without touching the account", async () => {
    localStorage.setItem("locale", "en");
    localStorage.setItem("token", "t");
    mockGet.mockResolvedValue(account("fr"));
    renderAuth("en");

    await waitFor(() => expect(shownLocale()).toBe("fr"));
    expect(mockPut).not.toHaveBeenCalled();
    expect(localStorage.getItem("locale")).toBeNull();
  });

  it("registers the account in the language of the page and ignores an old choice", async () => {
    localStorage.setItem("locale", "en");
    mockPost.mockResolvedValue({ token: "t", user: account("fr") });
    renderAuth("fr");
    await waitFor(() => expect(probe.auth.loading).toBe(false));

    await act(() => probe.auth.register("a@b.co", "password123"));

    expect(mockPost).toHaveBeenCalledWith("/auth/register", expect.objectContaining({ locale: "fr" }));
    expect(mockPut).not.toHaveBeenCalled();
    expect(localStorage.getItem("locale")).toBeNull();
    expect(shownLocale()).toBe("fr");
  });
});
